exercices.code:
#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    /* À compléter : affiche les diviseurs de n */
    printf("\n");
    return 0;
}

exercices.solution:
#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    for (int d = 1; d <= n; d++)
        if (n % d == 0)
            printf("%d ", d);
    printf("\n");
    return 0;
}

