#include <stdio.h>

int main(void) {
    int n;
    while (scanf("%d", &n) == 1)
        printf("%d\n", est_premier(n));
    return 0;
}

exercices.solution:
int est_premier(int n) {
    if (n < 2)
        return 0;
    for (int d = 2; d * d <= n; d++)
        if (n % d == 0)
            return 0;
    return 1;
}
